(** fuzz_role's compiled builder leaves pp_bytes at pp. For four inputs (the `role-master` seed W1, W7 with all
    three property kinds, W8 with a corruption, and T4 at every bound), the 19744 bytes the compiled code of
    LLVMFuzzerTestOneInput wrote at pp, read at its second malloc call (plain 0x13f48, UBSan 0x13f30) by running it in
    an RV64GC emulator, are written below as their non-zero runs; the plain and the UBSan image wrote the same bytes.
    Each lemma checks by computation that they are [pp_bytes] of the record [pod_build] makes of the input after the
    flags byte, and that pod_build reads that input to its end, as the code did. A witness, at the real instance,
    that the Layout text is the memory the walk of the builder must reach. Statement text and computation only. *)
From Stdlib Require Import ZArith List Lia Bool.
From LinuxProcessSemantics.LinuxProcessSem Require Import BvBase.
From OSSVerify.Proofs.reac_pw.fuzz_role.lib.Pod Require Import Cursor Model Layout Sat.
Import ListNotations.
Open Scope Z_scope.

(** The byte list of length n with the runs (offset, bytes) and 0 elsewhere (runs in increasing order, disjoint). *)
Fixpoint expand_from (pos : Z) (n : nat) (runs : list (Z * list Z)) : list Z :=
  match runs with
  | [] => repeat 0 n
  | (o, bs) :: runs' =>
      repeat 0 (Z.to_nat (o - pos)) ++ bs ++
      expand_from (o + Z.of_nat (length bs)) (n - Z.to_nat (o - pos) - length bs) runs'
  end.
Definition expand (n : nat) (runs : list (Z * list Z)) : list Z := expand_from 0 n runs.

